    12	  struct FilterChar {
    13	    unsigned int chr; 
    14	    unsigned int width; // width must always be < 256
    15	    typedef unsigned int Chr;
    16	    typedef unsigned int Width;
    17	    explicit FilterChar(Chr c = 0, Width w = 1) 
    18	      : chr(c), width(w) {}
    19	    FilterChar(Chr c, FilterChar o)
    20	      : chr(c), width(o.width) {}
    21	    static Width sum(const FilterChar * o, const FilterChar * stop) {
    22	      Width total = 0; 
    23	      for (; o != stop; ++o)
    24	        total += o->width;
    25	      return total;
    26	    }
    27	    static Width sum(const FilterChar * o, unsigned int size) {
    28	      return sum(o, o+size);
    29	    }
    30	    FilterChar(Chr c, const FilterChar * o, unsigned int size)
    31	      : chr(c), width(sum(o,size)) {}
    32	    FilterChar(Chr c, const FilterChar * o, const FilterChar * stop)
    33	      : chr(c), width(sum(o,stop)) {}
    34	    operator Chr () const {return chr;}
    35	    FilterChar & operator= (Chr c) {chr = c; return *this;}
    36	  };
    37	  
    38	  static inline bool operator==(FilterChar lhs, FilterChar rhs)
    39	  {
    40	    return lhs.chr == rhs.chr;
    41	  }
